Item.method_code:
const { odataFetch } = await import('../jsBundles/core.es.js');
const relationship = await window.newRelationship(
	false,
	null,
	null,
	window.NoRelatedOption
);
const sourceId = aras.getItemProperty(relationship, 'source_id');
const endpointConfigurationItem = (await odataFetch(`${options.itemTypeName}?$select=schema_definition&$filter=source_id eq '${sourceId}'&$orderBy=version desc&$top=1`)).value[0];

if (endpointConfigurationItem) {
  const { schema_definition: schemaDefinition } = endpointConfigurationItem;
  aras.setItemProperty(relationship, 'schema_definition', schemaDefinition);
}
